CREATE TABLE public.growth_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, kind text NOT NULL CHECK (kind IN ('competitor','task','evidence','analytics','client','subscription','followup','article','case_study')), payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.growth_records TO authenticated; GRANT ALL ON public.growth_records TO service_role; ALTER TABLE public.growth_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners manage growth records" ON public.growth_records FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE INDEX growth_records_user_kind_idx ON public.growth_records(user_id, kind);
CREATE TABLE public.agency_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, email text NOT NULL, member_id uuid, role text NOT NULL DEFAULT 'viewer' CHECK (role IN ('viewer','editor')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,email)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.agency_members TO authenticated; GRANT ALL ON public.agency_members TO service_role; ALTER TABLE public.agency_members ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners manage agency members" ON public.agency_members FOR ALL TO authenticated USING (owner_id=auth.uid()) WITH CHECK (owner_id=auth.uid()); CREATE POLICY "Invitees read their invitation" ON public.agency_members FOR SELECT TO authenticated USING (lower(email)=lower(auth.jwt()->>'email')); CREATE FUNCTION public.agency_access(owner uuid, edit boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.agency_members WHERE owner_id=owner AND member_id=auth.uid() AND (NOT edit OR role='editor')) $$; REVOKE ALL ON FUNCTION public.agency_access(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.agency_access(uuid,boolean) TO authenticated,service_role; CREATE POLICY "Agency members read clients and tasks" ON public.growth_records FOR SELECT TO authenticated USING (kind IN ('client','task') AND public.agency_access(user_id,false)); CREATE POLICY "Agency editors update clients and tasks" ON public.growth_records FOR UPDATE TO authenticated USING (kind IN ('client','task') AND public.agency_access(user_id,true)) WITH CHECK (kind IN ('client','task') AND public.agency_access(user_id,true)); CREATE POLICY "Admins manage followups and subscriptions" ON public.growth_records FOR ALL TO authenticated USING (kind IN ('followup','subscription','article','case_study') AND public.has_role(auth.uid(),'admin')) WITH CHECK (kind IN ('followup','subscription','article','case_study') AND public.has_role(auth.uid(),'admin'));